lesson('m1', 'mubtada', 'المبتدأ والخبر',
 'المبتدأ اسم مرفوع نبدأ به الكلام، والخبر هو ما نخبر به عنه فيتم المعنى، وهو مرفوع كذلك.',
 ['المبتدأ مرفوع، والخبر مرفوع.', 'الخبر ثلاثة أنواع: مفرد (العلمُ نافعٌ)، وجملة (العلمُ ينفعُ صاحبَه)، وشبه جملة (العلمُ في الصدور).', 'إذا كان الخبر جملة أو شبه جملة قيل: «في محل رفع خبر».', 'يتقدم الخبر وجوباً إذا كان شبه جملة والمبتدأ نكرة: في الدار رجلٌ.'],
 [('﴿محمدٌ رسولُ الله﴾', 'محمد: مبتدأ مرفوع، رسول: خبر مرفوع وهو مضاف، الله: مضاف إليه مجرور.'), ('﴿الحمدُ لله﴾', 'الحمد: مبتدأ مرفوع، لله: جار ومجرور متعلقان بمحذوف خبر.')],
 [('الخبر في «الطلابُ في الفصل»:', ['مفرد', 'جملة', 'شبه جملة'], 2, 'جار ومجرور.'), ('حكم المبتدأ والخبر:', ['مرفوعان', 'منصوبان', 'المبتدأ مرفوع والخبر منصوب'], 0, 'كلاهما مرفوع ما لم يدخل عليهما ناسخ.')],
 s=[1, 4, 15, 9, 39], r=[('ajurrumiyya', 'باب المبتدأ والخبر'), ('qatr-nada', 'باب المبتدأ والخبر'), ('alfiyya', 'الابتداء'), ('ibn-aqil', 'الابتداء')])

lesson('m1', 'kana', 'كان وأخواتها',
 'كان وأخواتها أفعال تدخل على المبتدأ والخبر، فترفع المبتدأ ويسمى اسمها، وتنصب الخبر ويسمى خبرها.',
 ['أخواتها: أصبح، أضحى، أمسى، ظلّ، بات، صار، ليس، ما زال، ما برح، ما فتئ، ما انفكّ، ما دام.', 'كان الجوُّ جميلاً: الجو اسم كان مرفوع، جميلاً خبر كان منصوب.', 'معانيها: أصبح وأمسى وأضحى للتوقيت، صار للتحول، ليس للنفي، ما زال وأخواتها للاستمرار.'],
 [('﴿وكان اللهُ عليماً حكيماً﴾', 'الله: اسم كان مرفوع، عليماً: خبر كان منصوب، حكيماً: خبر ثانٍ منصوب.'), ('﴿فأصبحتم بنعمته إخواناً﴾', 'التاء: اسم أصبح، إخواناً: خبر أصبح منصوب.')],
 [('«ليس» تعمل عمل:', ['إنّ', 'كان', 'ظنّ'], 1, 'ترفع الاسم وتنصب الخبر.'), ('خبر «صار» في «صار الماءُ ثلجاً»:', ['الماء', 'ثلجاً'], 1, 'خبر صار منصوب.')],
 s=[6, 19], r=[('ajurrumiyya', 'باب العوامل الداخلة'), ('qatr-nada', 'باب النواسخ'), ('alfiyya', 'كان وأخواتها'), ('ibn-aqil', 'كان وأخواتها')])

lesson('m1', 'inna', 'إنّ وأخواتها',
 'إنّ وأخواتها حروف تدخل على المبتدأ والخبر، فتنصب المبتدأ ويسمى اسمها، وترفع الخبر ويسمى خبرها، عكس كان.',
 ['أخواتها: أنّ (للتوكيد)، كأنّ (للتشبيه)، لكنّ (للاستدراك)، ليت (للتمني)، لعلّ (للترجي).', 'إنّ اللهَ غفورٌ: الله اسم إن منصوب، غفور خبر إن مرفوع.', 'إذا اتصلت بها «ما» الكافة بطل عملها: ﴿إنما المؤمنون إخوة﴾.'],
 [('﴿إنّ اللهَ غفورٌ رحيمٌ﴾', 'الله: اسم إن منصوب، غفور: خبر إن مرفوع، رحيم: خبر ثانٍ مرفوع.'), ('﴿لعلّكم تتقون﴾', 'الكاف: اسم لعل في محل نصب، وجملة تتقون: في محل رفع خبر لعل.')],
 [('معنى «ليت»:', ['التشبيه', 'التمني', 'الترجي'], 1, 'التمني يكون لما يبعد حصوله.'), ('«كأنّ القمرَ مصباحٌ»: «مصباح»:', ['اسم كأن', 'خبر كأن مرفوع', 'خبر كأن منصوب'], 1, 'إنّ وأخواتها ترفع الخبر.'), ('﴿إنما المؤمنون إخوة﴾: «المؤمنون»:', ['اسم إنّ', 'مبتدأ مرفوع'], 1, 'ما الكافة أبطلت عمل إنّ.')],
 s=[5, 18], r=[('ajurrumiyya', 'باب العوامل الداخلة'), ('alfiyya', 'إن وأخواتها'), ('ibn-aqil', 'إن وأخواتها')])

lesson('m1', 'naat', 'النعت (الصفة)',
 'النعت اسم يصف ما قبله ويتبعه في إعرابه: رفعه ونصبه وجره، وفي تعريفه وتنكيره.',
 ['جاء الرجلُ الكريمُ / رأيتُ الرجلَ الكريمَ / مررتُ بالرجلِ الكريمِ.', 'يتبع النعتُ منعوتَه في التذكير والتأنيث والإفراد والتثنية والجمع.', 'قد يكون النعت جملة بعد النكرة: رأيتُ رجلاً يقرأُ.'],
 [('﴿بلسانٍ عربيٍّ مبينٍ﴾', 'عربي: نعت مجرور، مبين: نعت ثانٍ مجرور، تبعا «لسان» المجرور.'), ('﴿صراطاً مستقيماً﴾', 'مستقيماً: نعت منصوب تابع لـ«صراطاً».')],
 [('«سكنتُ بيتاً واسعاً»: «واسعاً»:', ['حال', 'نعت منصوب', 'مفعول به'], 1, 'يصف «بيتاً» ويتبعه في النصب.'), ('النعت يتبع منعوته في:', ['الإعراب فقط', 'الإعراب والتعريف والتنكير', 'لا يتبعه'], 1, '')],
 s=[16, 32], r=[('ajurrumiyya', 'باب النعت'), ('qatr-nada', 'باب التوابع'), ('alfiyya', 'النعت')])

lesson('m1', 'atf', 'العطف',
 'العطف أن تجمع بين كلمتين بحرف عطف، فيأخذ المعطوف حكم المعطوف عليه في الإعراب.',
 ['حروف العطف: الواو (للجمع)، والفاء (للترتيب مع التعقيب)، وثُمّ (للترتيب مع التراخي)، وأو، وأم، وبل، ولكن، ولا، وحتى.', 'سافر محمدٌ وعليٌّ: عليٌّ معطوف مرفوع.', 'رأيتُ محمداً ثم عليّاً: عليّاً معطوف منصوب.'],
 [('﴿ثم أماتَه فأقبرَه﴾', 'الفاء عاطفة تفيد التعقيب.'), ('﴿يوم يقوم الناسُ لربّ العالمين﴾', '—')],
 [('الحرف الذي يفيد الترتيب مع التراخي:', ['الواو', 'الفاء', 'ثُمّ'], 2, ''), ('«قرأتُ الكتابَ والمجلةَ»: «المجلة»:', ['مفعول به', 'معطوف منصوب', 'نعت'], 1, 'معطوف على الكتاب.')],
 s=[17], r=[('ajurrumiyya', 'باب العطف'), ('alfiyya', 'عطف النسق')])

lesson('m1', 'jarr', 'المجرورات: حروف الجر والإضافة',
 'الاسم يُجرّ لسببين: أن يسبقه حرف جر، أو أن يكون مضافاً إليه.',
 ['حروف الجر: من، إلى، عن، على، في، رُبّ، الباء، الكاف، اللام، وحروف القسم (الواو والباء والتاء).', 'الإضافة: اسمان متلازمان، الأول «مضاف» يُعرب حسب موقعه، والثاني «مضاف إليه» مجرور دائماً: كتابُ الطالبِ.', 'المضاف لا يُنوّن ولا تدخله «أل».'],
 [('﴿بسمِ اللهِ الرحمنِ الرحيمِ﴾', 'الباء: حرف جر، اسم: اسم مجرور وهو مضاف، الله: مضاف إليه مجرور، الرحمن الرحيم: نعتان مجروران.'), ('﴿ربِّ العالمين﴾', 'العالمين: مضاف إليه مجرور وعلامة جره الياء لأنه ملحق بجمع المذكر السالم.')],
 [('«بابُ المسجدِ»: «المسجد»:', ['مضاف إليه', 'اسم مجرور بحرف', 'نعت'], 0, ''), ('هل يدخل التنوين على المضاف؟', ['نعم', 'لا'], 1, 'المضاف لا ينون.')],
 s=[4, 14, 15, 40], r=[('ajurrumiyya', 'باب المخفوضات'), ('alfiyya', 'حروف الجر'), ('alfiyya', 'الإضافة')])

lesson('m1', 'asma5', 'الأسماء الخمسة والمثنى والجمع',
 'هذه أسماء تُعرب بالحروف لا بالحركات، فاحفظ جدولها مرة واحدة يسهل عليك كثير من الإعراب.',
 ['الأسماء الخمسة: أبٌ، أخٌ، حمٌ، فو، ذو. تُرفع بالواو، وتنصب بالألف، وتجر بالياء، بشرط أن تكون مضافة لغير ياء المتكلم: جاء أبوك، رأيت أباك، مررت بأبيك.', 'المثنى: يرفع بالألف ويُنصب ويجر بالياء: الطالبان / الطالبَيْن.', 'جمع المذكر السالم: يرفع بالواو وينصب ويجر بالياء: المعلمون / المعلمِين.', 'جمع المؤنث السالم: يرفع بالضمة، وينصب ويجر بالكسرة: المعلماتُ / المعلماتِ.'],
 [('﴿وجاؤوا أباهم عشاءً يبكون﴾', 'أبا: مفعول به منصوب وعلامة نصبه الألف لأنه من الأسماء الخمسة.'), ('﴿هذان خصمان اختصموا﴾', 'خصمان: خبر مرفوع وعلامة رفعه الألف لأنه مثنى.')],
 [('«سلّمتُ على أخيك»: علامة جر «أخي»:', ['الكسرة', 'الياء'], 1, 'من الأسماء الخمسة.'), ('«المؤمنات» في حالة النصب علامتها:', ['الفتحة', 'الكسرة'], 1, 'جمع مؤنث سالم.')],
 s=[7, 9, 35, 39, 40], r=[('ajurrumiyya', 'باب معرفة علامات الإعراب'), ('sharh-qatr', 'الأسماء الستة')])

# ===================== المتوسط =====================
lesson('m2', 'naib', 'نائب الفاعل',
 'إذا حذفنا الفاعل وبنينا الفعل للمجهول، يقوم المفعول به مقام الفاعل فيُرفع ويسمى نائب فاعل.',
 ['بناء الماضي للمجهول: ضمّ أوله وكسر ما قبل آخره: كَتَبَ ← كُتِبَ.', 'بناء المضارع للمجهول: ضمّ أوله وفتح ما قبل آخره: يَكتُبُ ← يُكتَبُ.', 'نائب الفاعل مرفوع: كُتِبَ الدرسُ.'],
 [('﴿قُتِلَ أصحابُ الأخدود﴾', 'قُتل: فعل ماض مبني للمجهول، أصحاب: نائب فاعل مرفوع.'), ('﴿وقيلَ يا أرضُ ابلعي ماءك﴾', '—')],
 [('«فُتِحَ البابُ»: «الباب»:', ['فاعل', 'نائب فاعل', 'مفعول به'], 1, 'الفعل مبني للمجهول.'), ('المضارع المبني للمجهول من «يَفهَم»:', ['يُفهِم', 'يُفهَم', 'فُهِم'], 1, 'ضم الأول وفتح ما قبل الآخر.')],
 s=[20], r=[('ajurrumiyya', 'باب المفعول الذي لم يسم'), ('qatr-nada', 'باب النائب عن الفاعل'), ('alfiyya', 'النائب عن الفاعل')])

lesson('m2', 'zanna', 'ظنّ وأخواتها',
 'أفعال تدخل على المبتدأ والخبر فتنصبهما معاً مفعولين: الأول والثاني.',
 ['أفعال القلوب: ظنّ، حسب، خال، زعم، علم، رأى، وجد.', 'أفعال التحويل: صيّر، جعل، اتّخذ.', 'ظننتُ الجوَّ بارداً: الجو مفعول به أول، بارداً مفعول به ثان.'],
 [('﴿واتخذ اللهُ إبراهيمَ خليلاً﴾', 'إبراهيم: مفعول به أول، خليلاً: مفعول به ثان.'), ('﴿إنهم يرونه بعيداً﴾', 'الهاء: مفعول أول، بعيداً: مفعول ثان.')],
 [('«ظنّ» تنصب:', ['مفعولاً واحداً', 'مفعولين'], 1, ''), ('«جعلتُ الطينَ إبريقاً»: «إبريقاً»:', ['حال', 'مفعول به ثان', 'تمييز'], 1, 'جعل هنا للتحويل.')],
 s=[29], r=[('ajurrumiyya', 'باب العوامل الداخلة'), ('alfiyya', 'ظل وأخواتها')])

lesson('m2', 'mutlaq', 'المفعول المطلق',
 'مصدر منصوب من لفظ الفعل يُذكر بعده لتوكيده أو بيان نوعه أو عدده.',
 ['للتوكيد: ﴿وكلّم الله موسى تكليماً﴾.', 'لبيان النوع: سرتُ سيرَ العقلاء.', 'لبيان العدد: ضربتُ ضربتين.', 'ينوب عنه: كلّ وبعض المضافان إلى المصدر، وصفته، وعدده: ﴿فلا تميلوا كلَّ الميل﴾.'],
 [('﴿وكلّمَ اللهُ موسى تكليماً﴾', 'تكليماً: مفعول مطلق منصوب.'), ('﴿وتحبون المالَ حُبّاً جمّاً﴾', 'حباً: مفعول مطلق منصوب، جماً: نعت منصوب.')],
 [('«فرحتُ فرحاً عظيماً»: «فرحاً»:', ['مفعول به', 'مفعول مطلق', 'حال'], 1, 'مصدر من لفظ الفعل.')],
 s=[21], r=[('ajurrumiyya', 'باب المصدر'), ('alfiyya', 'المفعول المطلق')])

lesson('m2', 'zarf', 'المفعول فيه (الظرف) والمفعول لأجله والمفعول معه',
 'منصوبات تبيّن زمان الفعل أو مكانه، أو سببه، أو ما وقع معه.',
 ['ظرف الزمان: يومَ، ليلةَ، صباحاً، غداً... صمتُ يومَ الخميس.', 'ظرف المكان: أمامَ، خلفَ، فوقَ، تحتَ، عندَ... جلستُ أمامَ المعلم.', 'المفعول لأجله: مصدر قلبي يبين سبب الفعل: وقفتُ احتراماً للمعلم.', 'المفعول معه: اسم بعد واو بمعنى «مع»: سرتُ والنيلَ.'],
 [('﴿يخافون ربَّهم من فوقهم﴾', '—'), ('﴿يجعلون أصابعهم في آذانهم من الصواعق حذرَ الموت﴾', 'حذرَ: مفعول لأجله منصوب.')],
 [('«سافرتُ ليلاً»: «ليلاً»:', ['مفعول به', 'ظرف زمان', 'حال'], 1, ''), ('«قمتُ إكراماً لأبي»: «إكراماً»:', ['مفعول مطلق', 'مفعول لأجله'], 1, 'يبين سبب القيام.')],
 s=[30, 31], r=[('ajurrumiyya', 'باب ظرف الزمان'), ('ajurrumiyya', 'باب المفعول من أجله'), ('ajurrumiyya', 'باب المفعول معه'), ('alfiyya', 'المفعول فيه')])

lesson('m2', 'hal', 'الحال',
 'اسم منصوب نكرة يبيّن هيئة صاحبه وقت وقوع الفعل، ويجيب عن سؤال: كيف؟',
 ['الحال منصوب نكرة غالباً، وصاحبه معرفة غالباً.', 'جاء الطالبُ مسرعاً: كيف جاء؟ مسرعاً.', 'قد تكون الحال جملة: جاء الطالبُ وهو يبتسم.'],
 [('﴿فخرجَ منها خائفاً يترقّب﴾', 'خائفاً: حال منصوب، وجملة يترقب: حال ثانية في محل نصب.'), ('﴿وخُلِق الإنسانُ ضعيفاً﴾', 'ضعيفاً: حال منصوب.')],
 [('الحال تجيب عن سؤال:', ['متى؟', 'كيف؟', 'أين؟'], 1, ''), ('«رجع الجيشُ منتصراً»: «منتصراً»:', ['نعت', 'حال', 'خبر'], 1, 'يبين هيئة الجيش، والجيش معرفة.')],
 s=[22], r=[('ajurrumiyya', 'باب الحال'), ('qatr-nada', 'باب الحال'), ('alfiyya', 'الحال')])

lesson('m2', 'tamyiz', 'التمييز',
 'اسم نكرة منصوب يزيل الغموض عما قبله، كالعدد والوزن والكيل والمساحة، أو يفسّر نسبةً في الجملة.',
 ['تمييز العدد: اشتريتُ عشرين كتاباً.', 'تمييز الوزن والكيل: اشتريتُ كيلو عسلاً.', 'تمييز النسبة: ﴿واشتعلَ الرأسُ شيباً﴾، طاب محمدٌ نفساً.'],
 [('﴿إني رأيتُ أحدَ عشرَ كوكباً﴾', 'كوكباً: تمييز منصوب.'), ('﴿واشتعل الرأسُ شيباً﴾', 'شيباً: تمييز نسبة منصوب.')],
 [('الفرق بين الحال والتمييز:', ['الحال يبين الهيئة، والتمييز يزيل الإبهام', 'لا فرق'], 0, ''), ('«امتلأ الإناءُ ماءً»: «ماءً»:', ['مفعول به', 'تمييز', 'حال'], 1, '')],
 s=[23], r=[('ajurrumiyya', 'باب التمييز'), ('alfiyya', 'التمييز')])

lesson('m2', 'istithna', 'الاستثناء',
 'إخراج ما بعد «إلا» أو إحدى أخواتها من حكم ما قبلها.',
 ['أدواته: إلا، غير، سوى، خلا، عدا، حاشا.', 'إن كان الكلام تاماً مثبتاً وجب نصب المستثنى: نجح الطلابُ إلا خالداً.', 'إن كان تاماً منفياً جاز النصب والإتباع: ما نجح الطلابُ إلا خالداً/خالدٌ.', 'إن كان ناقصاً (المستثنى منه محذوف) أُعرب ما بعد إلا حسب موقعه: ما نجح إلا خالدٌ (فاعل).', 'المستثنى بغير وسوى يكون مجروراً بالإضافة، وتأخذ «غير» حكم الاسم الواقع بعد إلا.'],
 [('﴿فسجدوا إلا إبليسَ﴾', 'إبليس: مستثنى بإلا منصوب.'), ('﴿وما محمدٌ إلا رسولٌ﴾', 'إلا هنا أداة حصر، ورسول: خبر مرفوع.')],
 [('«حضر الضيوفُ إلا ضيفاً»: حكم «ضيفاً»:', ['النصب وجوباً', 'الرفع', 'الجر'], 0, 'تام مثبت.'), ('«ما جاء إلا عليٌّ»: «عليّ»:', ['مستثنى منصوب', 'فاعل مرفوع'], 1, 'الكلام ناقص فيُعرب حسب موقعه.')],
 s=[24, 25], r=[('ajurrumiyya', 'باب الاستثناء'), ('alfiyya', 'الاستثناء')])

lesson('m2', 'la', 'لا النافية للجنس',
 'حرف ينفي الخبر عن جنس اسمها كله، ويعمل عمل «إنّ».',
 ['شروطها: أن يكون اسمها وخبرها نكرتين، وأن يتصل بها اسمها.', 'إن كان اسمها مفرداً (غير مضاف ولا شبيه بالمضاف) بُني على ما يُنصب به: لا رجلَ في الدار.', 'إن كان مضافاً نُصب: لا طالبَ علمٍ مذمومٌ.'],
 [('﴿لا ريبَ فيه﴾', 'ريبَ: اسم لا مبني على الفتح في محل نصب، فيه: جار ومجرور متعلقان بمحذوف خبر لا.'), ('لا إلهَ إلا اللهُ', 'إله: اسم لا مبني على الفتح في محل نصب، والخبر محذوف تقديره: حقٌّ.')],
 [('«لا طالبَ في الفصل»: «طالب»:', ['اسم لا مبني على الفتح', 'مبتدأ', 'مفعول به'], 0, '')],
 s=[25], r=[('ajurrumiyya', 'باب لا'), ('alfiyya', 'لا التي لنفى الجنس')])

lesson('m2', 'nida', 'المنادى',
 'الاسم الذي يأتي بعد حرف نداء (يا، أيا، هيا، أيْ، الهمزة).',
 ['المفرد العلم والنكرة المقصودة: يُبنى على ما يرفع به: يا محمدُ، يا رجلُ (لرجل معين).', 'المضاف والشبيه بالمضاف والنكرة غير المقصودة: يُنصب: يا عبدَ الله، يا طالعاً جبلاً، يا غافلاً تنبّه.'],
 [('﴿يا نوحُ اهبطْ بسلام﴾', 'نوح: منادى مفرد علم مبني على الضم في محل نصب.'), ('﴿يا أهلَ الكتاب﴾', 'أهل: منادى منصوب لأنه مضاف.')],
 [('«يا عبدَ الله»: «عبد»:', ['مبني على الضم', 'منصوب لأنه مضاف'], 1, '')],
 s=[26], r=[('ajurrumiyya', 'باب المنادى'), ('alfiyya', 'النداء')])

lesson('m2', 'tawkid', 'التوكيد والبدل',
 'من التوابع: التوكيد يقوّي المعنى ويرفع احتمال المجاز، والبدل يذكر المقصود بالحكم بلا واسطة.',
 ['التوكيد اللفظي: تكرار اللفظ: جاء جاء محمد.', 'التوكيد المعنوي: بالنفس، والعين، وكلّ، وجميع، وكلا وكلتا، مضافة إلى ضمير يعود على المؤكَّد: حضر الطلابُ كلُّهم.', 'البدل: مطابق (كل من كل): جاء أخوك محمدٌ، وبعض من كل: أكلتُ الرغيفَ نصفَه، واشتمال: أعجبني الطالبُ خلقُه.'],
 [('﴿فسجد الملائكةُ كلُّهم أجمعون﴾', 'كلّ: توكيد مرفوع، أجمعون: توكيد ثانٍ مرفوع بالواو.'), ('﴿اهدنا الصراطَ المستقيمَ صراطَ الذين أنعمتَ عليهم﴾', 'صراطَ الثانية: بدل مطابق منصوب.')],
 [('«قرأتُ الكتابَ ثلثَه»: «ثلث»:', ['توكيد', 'بدل بعض من كل', 'نعت'], 1, '')],
 s=[27, 28], r=[('ajurrumiyya', 'باب التوكيد'), ('ajurrumiyya', 'باب البدل'), ('alfiyya', 'التوكيد'), ('alfiyya', 'البدل')])

lesson('m2', 'nawasib', 'نواصب المضارع وجوازمه',
 'المضارع يُنصب إذا سبقه ناصب، ويُجزم إذا سبقه جازم.',
 ['النواصب: أن، لن، كي، إذن، ولام التعليل ولام الجحود وحتى وفاء السببية وواو المعية (بأن مضمرة).', 'الجوازم لفعل واحد: لم، لمّا، لام الأمر، لا الناهية.', 'الجوازم لفعلين (أدوات الشرط): إنْ، مَن، ما، مهما، متى، أين، حيثما، كيفما...: إنْ تدرسْ تنجحْ.'],
 [('﴿لن تنالوا البرَّ حتى تنفقوا﴾', 'تنالوا وتنفقوا: منصوبان وعلامة نصبهما حذف النون.'), ('﴿ومن يتقِ اللهَ يجعلْ له مخرجاً﴾', 'يتق: فعل الشرط مجزوم بحذف الياء، يجعل: جواب الشرط مجزوم بالسكون.')],
 [('«لم» تجزم:', ['فعلاً واحداً', 'فعلين'], 0, ''), ('«إنْ تصدقْ تُحترمْ»: الفعلان:', ['مرفوعان', 'منصوبان', 'مجزومان'], 2, 'إنْ الشرطية تجزم فعلين.')],
 s=[10, 11, 38], r=[('qatr-nada', 'ومضارع'), ('alfiyya', 'إعراب الفعل'), ('alfiyya', 'عوامل الجزم')])

# ===================== المتقدم =====================
lesson('m3', 'muqaddar', 'الإعراب التقديري والمحلّي',
 'أحياناً لا تظهر العلامة على آخر الكلمة، فنقول إنها «مقدّرة». وأحياناً تكون الكلمة مبنية أو جملة فنقول إنها «في محل» رفع أو نصب أو جر.',
 ['المقصور (آخره ألف): تقدّر عليه الحركات الثلاث للتعذر: جاء الفتى، رأيت الفتى، مررت بالفتى.', 'المنقوص (آخره ياء): تقدّر عليه الضمة والكسرة للثقل، وتظهر الفتحة: جاء القاضي، مررت بالقاضي، رأيت القاضيَ.', 'المضاف لياء المتكلم: تقدّر عليه الحركات لاشتغال المحل بالحركة المناسبة: هذا كتابي.', 'الإعراب المحلي: للمبنيات والجمل: «هذا» في محل رفع، والجملة الواقعة خبراً في محل رفع.'],
 [('﴿وجاء من أقصى المدينة رجلٌ يسعى﴾', 'أقصى: اسم مجرور وعلامة جره الكسرة المقدرة على الألف للتعذر، وجملة يسعى: في محل رفع نعت.'), ('﴿يومَ يدعُ الداعِ﴾', 'الداع: فاعل مرفوع بضمة مقدرة على الياء المحذوفة.')],
 [('علامة رفع «الهدى» في: الهدى نورٌ:', ['ضمة ظاهرة', 'ضمة مقدرة للتعذر', 'ضمة مقدرة للثقل'], 1, 'اسم مقصور.'), ('علامة نصب «القاضيَ» في: رأيتُ القاضيَ:', ['فتحة ظاهرة', 'فتحة مقدرة'], 0, 'الفتحة تظهر على المنقوص لخفتها.')],
 s=[36, 37, 21], r=[('sharh-qatr', 'الإعراب التقديري'), ('alfiyya', 'المعرب والمبني')])

lesson('m3', 'mamnu', 'الممنوع من الصرف',
 'أسماء لا يدخلها التنوين ولا الكسرة، فتُجرّ بالفتحة نيابة عن الكسرة، إلا إذا أضيفت أو دخلتها «أل».',
 ['يُمنع لعلة واحدة: صيغة منتهى الجموع (مساجد، مصابيح)، وألف التأنيث (صحراء، حبلى).', 'يُمنع العلَم لعلتين: مع التأنيث (فاطمة، زينب)، أو العجمة (إبراهيم، يوسف)، أو التركيب المزجي (حضرموت)، أو زيادة الألف والنون (عثمان)، أو وزن الفعل (أحمد، يزيد)، أو العدل (عمر).', 'تُمنع الصفة لعلتين: وزن «أفعل» (أكبر، أحمر)، أو «فعلان» (عطشان)، أو العدل (مثنى، أُخَر).', 'إذا أضيف أو دخلته أل جُرّ بالكسرة: صليتُ في المساجدِ، في مساجدِ المدينة.'],
 [('﴿ولقد زيّنّا السماء الدنيا بمصابيحَ﴾', 'مصابيح: اسم مجرور وعلامة جره الفتحة نيابة عن الكسرة لأنه ممنوع من الصرف.'), ('﴿وأوحينا إلى إبراهيمَ﴾', 'إبراهيم: مجرور بالفتحة للعلمية والعجمة.')],
 [('«مررتُ بأحمدَ»: علامة جر «أحمد»:', ['الكسرة', 'الفتحة'], 1, 'علم على وزن الفعل.'), ('«صليتُ في المساجدِ»:', ['تجر بالفتحة', 'تجر بالكسرة لدخول أل'], 1, '')],
 s=[32], r=[('qatr-nada', 'باب موانع صرف الاسم'), ('alfiyya', 'ما لا ينصرف')])

lesson('m3', 'adad', 'العدد',
 'للعدد قواعد في التذكير والتأنيث وفي تمييزه، وهي من أكثر ما يخطئ فيه الناس.',
 ['1 و2: يوافقان المعدود ويأتيان بعده صفة: رجلٌ واحدٌ، امرأتان اثنتان.', 'من 3 إلى 10: يخالف المعدودَ تذكيراً وتأنيثاً، وتمييزه جمع مجرور: ثلاثةُ رجالٍ، ثلاثُ نساءٍ.', '11 و12: يوافقان المعدود في جزأيهما، و13–19: الجزء الأول يخالف والثاني يوافق، وتمييزها مفرد منصوب: ثلاثةَ عشرَ رجلاً، ثلاثَ عشرةَ امرأةً.', 'ألفاظ العقود (20–90): لا تتغير، وتمييزها مفرد منصوب: عشرون طالباً.', 'المائة والألف: تمييزهما مفرد مجرور: مائةُ رجلٍ، ألفُ امرأةٍ.'],
 [('﴿سبعَ سمواتٍ﴾', 'سبع خالف المعدود (سموات مؤنث)، وتمييزه جمع مجرور.'), ('﴿إن عدة الشهور عند الله اثنا عشرَ شهراً﴾', 'اثنا عشر: وافق المعدود المذكر، وشهراً: تمييز مفرد منصوب.')],
 [('الصواب:', ['ثلاث رجال', 'ثلاثة رجال'], 1, 'العدد 3–10 يخالف المعدود.'), ('الصواب:', ['خمسة عشر طالبة', 'خمس عشرة طالبة'], 1, 'الجزء الأول يخالف والثاني يوافق.')],
 s=[23], r=[('qatr-nada', 'باب العدد'), ('alfiyya', 'العدد')])

lesson('m3', 'taajjub', 'أساليب: التعجب، والمدح والذم',
 'أساليب لها صيغ ثابتة، تُعرب بطريقة محفوظة.',
 ['صيغتا التعجب: «ما أفعلَه» (ما أجملَ السماءَ!)، و«أفعِلْ به» (أجمِلْ بالسماء!).', 'ما: نكرة تامة بمعنى شيء مبتدأ، وأجمل: فعل ماض جامد، وفاعله ضمير مستتر، والسماء مفعول به، والجملة خبر.', 'المدح بـ«نِعم» والذم بـ«بئس»: نِعمَ الخلقُ الصدقُ: نعم فعل ماض جامد، الخلق فاعل، الصدق المخصوص بالمدح.'],
 [('﴿نِعمَ العبدُ إنه أوّاب﴾', 'العبد: فاعل نعم مرفوع.'), ('﴿فما أصبرَهم على النار﴾', 'أسلوب تعجب: ما أفعله.')],
 [('«ما أجملَ» نوع الفعل «أجمل»:', ['فعل أمر', 'فعل ماض جامد', 'اسم تفضيل'], 1, '')],
 s=[33, 34], r=[('qatr-nada', 'باب التعجب'), ('alfiyya', 'التعجب'), ('alfiyya', 'نعم وبئس')])

lesson('m3', 'jumal', 'الجمل التي لها محل من الإعراب والتي لا محل لها',
 'الجملة إذا حلّت محل مفرد كان لها محله من الإعراب، وإلا فلا محل لها. وهذا مفتاح إعراب النصوص الطويلة.',
 ['جمل لها محل: الخبرية (في محل رفع خبر)، والحالية (في محل نصب حال)، والمفعولية (بعد القول: في محل نصب مفعول به)، والمضاف إليها (بعد إذ وإذا وحين: في محل جر)، وجملة جواب الشرط المقترنة بالفاء أو إذا (في محل جزم)، والتابعة لمفرد (نعتاً وغيره).', 'جمل لا محل لها: الابتدائية، والاستئنافية، والصلة (بعد الاسم الموصول)، والاعتراضية، والتفسيرية، وجواب القسم، وجواب الشرط غير الجازم.'],
 [('﴿قال إني عبدُ الله﴾', 'جملة «إني عبد الله»: في محل نصب مقول القول.'), ('﴿الذي خلقَ فسوّى﴾', 'جملة «خلق»: صلة الموصول لا محل لها من الإعراب.')],
 [('جملة صلة الموصول:', ['في محل رفع', 'لا محل لها'], 1, ''), ('«جاء الطالبُ يضحكُ»: جملة يضحك:', ['في محل نصب حال', 'في محل رفع خبر'], 0, '')],
 s=[12], r=[('sharh-qatr', 'الجمل'), ('sharh-shudhur', 'الجمل')])

# ===== مدرّب الإعراب: جمل مقسّمة كلمةً كلمة =====
# كل كلمة: (الكلمة، الدور، الحكم، نص الإعراب الكامل)
# الحكم: رفع/نصب/جر/جزم/مبني
S = {}
def sent(n, lvl, src, toks): S[n] = dict(n=n, lvl=lvl, src=src, w=[dict(w=a, r=b, h=c, x=d) for a, b, c, d in toks])
M = 'مبني'
sent(1, 'm1', '', [('العلمُ', 'مبتدأ', 'رفع', 'مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة على آخره.'), ('نورٌ', 'خبر', 'رفع', 'خبر المبتدأ مرفوع وعلامة رفعه الضمة الظاهرة على آخره.')])
sent(2, 'm1', '', [('حضرَ', 'فعل ماض', M, 'فعل ماضٍ مبني على الفتح.'), ('الطالبُ', 'فاعل', 'رفع', 'فاعل مرفوع وعلامة رفعه الضمة الظاهرة على آخره.')])
sent(3, 'm1', '', [('قرأَ', 'فعل ماض', M, 'فعل ماضٍ مبني على الفتح.'), ('محمدٌ', 'فاعل', 'رفع', 'فاعل مرفوع وعلامة رفعه الضمة الظاهرة على آخره.'), ('القرآنَ', 'مفعول به', 'نصب', 'مفعول به منصوب وعلامة نصبه الفتحة الظاهرة على آخره.')])
