sent(5, 'm1', '', [('إنّ', 'حرف ناسخ', M, 'حرف توكيد ونصب مبني على الفتح.'), ('الصدقَ', 'اسم إن', 'نصب', 'اسم إنّ منصوب وعلامة نصبه الفتحة الظاهرة على آخره.'), ('منجاةٌ', 'خبر إن', 'رفع', 'خبر إنّ مرفوع وعلامة رفعه الضمة الظاهرة على آخره.')])
sent(6, 'm1', '', [('كانَ', 'فعل ناسخ', M, 'فعل ماضٍ ناقص (ناسخ) مبني على الفتح.'), ('الجوُّ', 'اسم كان', 'رفع', 'اسم كان مرفوع وعلامة رفعه الضمة الظاهرة على آخره.'), ('جميلاً', 'خبر كان', 'نصب', 'خبر كان منصوب وعلامة نصبه الفتحة الظاهرة على آخره.')])
sent(7, 'm1', '', [('جاءَ', 'فعل ماض', M, 'فعل ماضٍ مبني على الفتح.'), ('أبوكَ', 'فاعل', 'رفع', 'فاعل مرفوع وعلامة رفعه الواو لأنه من الأسماء الخمسة، وهو مضاف، والكاف ضمير متصل مبني على الفتح في محل جر مضاف إليه.')])
sent(8, 'm1', '', [('رأيتُ', 'فعل وفاعل', M, 'فعل ماضٍ مبني على السكون لاتصاله بتاء الفاعل، والتاء ضمير متصل مبني على الضم في محل رفع فاعل.'), ('المعلمَيْنِ', 'مفعول به', 'نصب', 'مفعول به منصوب وعلامة نصبه الياء لأنه مثنى، والنون عوض عن التنوين في الاسم المفرد.')])
sent(9, 'm1', '', [('المسلمون', 'مبتدأ', 'رفع', 'مبتدأ مرفوع وعلامة رفعه الواو لأنه جمع مذكر سالم.'), ('صادقون', 'خبر', 'رفع', 'خبر مرفوع وعلامة رفعه الواو لأنه جمع مذكر سالم.')])
sent(10, 'm1', '', [('لم', 'حرف جزم', M, 'حرف نفي وجزم وقلب مبني على السكون.'), ('يكتبِ', 'فعل مضارع', 'جزم', 'فعل مضارع مجزوم بلم وعلامة جزمه السكون، وحُرّك بالكسر لالتقاء الساكنين.'), ('الطالبُ', 'فاعل', 'رفع', 'فاعل مرفوع وعلامة رفعه الضمة.'), ('الدرسَ', 'مفعول به', 'نصب', 'مفعول به منصوب وعلامة نصبه الفتحة.')])
sent(11, 'm1', '', [('لن', 'حرف نصب', M, 'حرف نفي ونصب واستقبال مبني على السكون.'), ('يفوزَ', 'فعل مضارع', 'نصب', 'فعل مضارع منصوب بلن وعلامة نصبه الفتحة الظاهرة على آخره.'), ('الكسولُ', 'فاعل', 'رفع', 'فاعل مرفوع وعلامة رفعه الضمة.')])
sent(12, 'm1', '', [('الطلابُ', 'مبتدأ', 'رفع', 'مبتدأ مرفوع وعلامة رفعه الضمة.'), ('يكتبون', 'خبر (جملة)', 'رفع', 'فعل مضارع مرفوع وعلامة رفعه ثبوت النون لأنه من الأفعال الخمسة، والواو ضمير متصل مبني على السكون في محل رفع فاعل، والجملة الفعلية في محل رفع خبر المبتدأ.')])
sent(13, 'm1', '', [('اكتبْ', 'فعل أمر', M, 'فعل أمر مبني على السكون، والفاعل ضمير مستتر وجوباً تقديره أنت.'), ('درسَكَ', 'مفعول به', 'نصب', 'مفعول به منصوب وعلامة نصبه الفتحة، وهو مضاف، والكاف ضمير متصل مبني على الفتح في محل جر مضاف إليه.')])
